    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    non_zero = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c]:
                non_zero.add(grid[r][c])
    if len(non_zero) < 2:
        return grid  # nothing to do

    # Identify rectangle color
    rect_color = None
    for col in non_zero:
        # compute bounding box and count
        min_r = rows
        max_r = -1
        min_c = cols
        max_c = -1
        cnt = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == col:
                    cnt += 1
                    if r < min_r: min_r = r
                    if r > max_r: max_r = r
                    if c < min_c: min_c = c
                    if c > max_c: max_c = c
        area = (max_r - min_r + 1) * (max_c - min_c + 1)
        if cnt == area:
            rect_color = col
            rect_r_min, rect_r_max = min_r, max_r
            rect_c_min, rect_c_max = min_c, max_c
            break

    if rect_color is None:
        return grid  # should not happen

    # The remaining non‑zero color is the shape to keep
    shape_color = (non_zero - {rect_color}).pop()

    # Remove the rectangle
    for r in range(rect_r_min, rect_r_max + 1):
        for c in range(rect_c_min, rect_c_max + 1):
            grid[r][c] = 0

    # Bounding box of the shape (using original positions)
    min_c_shape = cols
    max_c_shape = -1
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == shape_color:
                if c < min_c_shape:
                    min_c_shape = c
                if c > max_c_shape:
                    max_c_shape = c

    # Process each row inside the rectangle, except the bottom row
    for r in range(rect_r_min, rect_r_max):
        # columns with shape in this row
        shape_cols = [c for c in range(cols) if grid[r][c] == shape_color]
        if not shape_cols:
            continue
        # split into contiguous blocks
        blocks = []
        shape_cols.sort()
        start = shape_cols[0]
        prev = start
        for c in shape_cols[1:]:
            if c == prev + 1:
                prev = c
            else:
                blocks.append((start, prev))
                start = c
                prev = c
        blocks.append((start, prev))

        # rightmost block
        block_start, block_end = blocks[-1]
        block_len = block_end - block_start + 1
        # decide whether to mirror this block
        if block_len >= 2:
            to_mirror = list(range(block_start, block_end + 1))
        elif block_len == 1 and len(blocks) == 1:
            to_mirror = [block_start]
        else:
            to_mirror = []

        for c in to_mirror:
            c_mir = min_c_shape + max_c_shape - c
            if rect_c_min <= c_mir <= rect_c_max:
                grid[r][c_mir] = shape_color

    # Global addition: mirror of the rightmost shape column inside the rectangle
    max_c_in_rect = -1
    for r in range(rect_r_min, rect_r_max + 1):
        for c in range(cols):
            if grid[r][c] == shape_color:
                if c > max_c_in_rect:
                    max_c_in_rect = c
